pub fn flip_case(s: Vec<char>) -> Vec<char> {
    s.into_iter()
        .map(|c| match c {
            'a'..='z' => ((c as u8) - b'a' + b'A') as char,
            'A'..='Z' => ((c as u8) - b'A' + b'a') as char,
            _ => c, // non-ASCII letters (and everything else) stay unchanged
        })
        .collect()
}